        private static void CreateLibraryUpperGalleryDetails(Transform root, string prefix, bool past, Materials materials, Vector3 c, Material wood, Material trim)
        {
            var seamMaterials = past
                ? new[] { trim, wood, trim, wood }
                : new[] { materials.Dust, materials.Dust, materials.Dust, materials.Dust };

            var leftBalconySeamXs = new[] { -0.56f, -0.18f, 0.20f, 0.58f };
            var rightBalconySeamXs = new[] { -0.56f, -0.18f, 0.20f, 0.58f };
            var backGallerySeamZs = new[] { -0.46f, -0.14f, 0.18f, 0.50f };

            for (var i = 0; i < leftBalconySeamXs.Length; i++)
            {
                CreateLandmarkCube(
                    $"{prefix}_Library_UpperGallery_LeftBalcony_PlankSeam_{i}",
                    root,
                    c + new Vector3(-4.18f + leftBalconySeamXs[i], 2.095f, 0.10f),
                    new Vector3(0.024f, 0.012f, 9.74f),
                    Quaternion.identity,
                    seamMaterials[i],
                    false,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                    $"{prefix}.library.upper_gallery.left_balcony_plank_seam.{i}");

                CreateLandmarkCube(
                    $"{prefix}_Library_UpperGallery_RightBalcony_PlankSeam_{i}",
                    root,
                    c + new Vector3(4.18f + rightBalconySeamXs[i], 2.095f, 0.10f),
                    new Vector3(0.024f, 0.012f, 9.74f),
                    Quaternion.identity,
                    seamMaterials[i],
                    false,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                    $"{prefix}.library.upper_gallery.right_balcony_plank_seam.{i}");

                CreateLandmarkCube(
                    $"{prefix}_Library_UpperGallery_BackGallery_PlankSeam_{i}",
                    root,
                    c + new Vector3(0.00f, 2.095f, 6.45f + backGallerySeamZs[i]),
                    new Vector3(8.84f, 0.012f, 0.024f),
                    Quaternion.identity,
                    seamMaterials[i],
                    false,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                    $"{prefix}.library.upper_gallery.back_gallery_plank_seam.{i}");
            }

            CreateLandmarkCube(
                $"{prefix}_Library_UpperGallery_LeftBalcony_FrontEdgeShadow",
                root,
                c + new Vector3(-4.18f, 2.005f, -5.00f),
                new Vector3(1.42f, 0.024f, 0.052f),
                Quaternion.identity,
                past ? trim : materials.Dust,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.upper_gallery.left_balcony_front_edge_shadow");
            CreateLandmarkCube(
                $"{prefix}_Library_UpperGallery_LeftBalcony_FrontEdgeHighlight",
                root,
                c + new Vector3(-4.18f, 2.108f, -4.98f),
                new Vector3(1.32f, 0.016f, 0.028f),
                Quaternion.identity,
                past ? wood : trim,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.upper_gallery.left_balcony_front_edge_highlight");

            CreateLandmarkCube(
                $"{prefix}_Library_UpperGallery_RightBalcony_FrontEdgeShadow",
                root,
                c + new Vector3(4.18f, 2.005f, -5.00f),
                new Vector3(1.42f, 0.024f, 0.052f),
                Quaternion.identity,
                past ? trim : materials.Dust,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.upper_gallery.right_balcony_front_edge_shadow");
            CreateLandmarkCube(
                $"{prefix}_Library_UpperGallery_RightBalcony_FrontEdgeHighlight",
                root,
                c + new Vector3(4.18f, 2.108f, -4.98f),
                new Vector3(1.32f, 0.016f, 0.028f),
                Quaternion.identity,
                past ? wood : trim,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.upper_gallery.right_balcony_front_edge_highlight");

            CreateLandmarkCube(
                $"{prefix}_Library_UpperGallery_BackGallery_FrontEdgeShadow",
                root,
                c + new Vector3(0.00f, 2.005f, 5.81f),
                new Vector3(8.92f, 0.024f, 0.052f),
                Quaternion.identity,
                past ? trim : materials.Dust,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.upper_gallery.back_gallery_front_edge_shadow");
            CreateLandmarkCube(
                $"{prefix}_Library_UpperGallery_BackGallery_FrontEdgeHighlight",
                root,
                c + new Vector3(0.00f, 2.108f, 5.84f),
                new Vector3(8.72f, 0.016f, 0.028f),
                Quaternion.identity,
                past ? wood : trim,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.upper_gallery.back_gallery_front_edge_highlight");

            var leftRailZs = new[] { -4.20f, -2.10f, 0f, 2.10f, 4.20f };
            var rightRailZs = new[] { -4.20f, -2.10f, 0f, 2.10f, 4.20f };
            var backRailXs = new[] { -3.80f, -1.90f, 0f, 1.90f, 3.80f };
            for (var i = 0; i < leftRailZs.Length; i++)
            {
                var leftHeight = past ? 0.62f : (i == 2 ? 0.46f : 0.58f);
                var leftMaterial = past ? trim : (i == 2 ? materials.Dust : trim);
                CreateLandmarkCube(
                    $"{prefix}_Library_UpperGallery_LeftRail_Baluster_{i}",
                    root,
                    c + new Vector3(-4.84f, 2.44f, 0.10f + leftRailZs[i]),
                    new Vector3(0.07f, leftHeight, 0.07f),
                    Quaternion.identity,
                    leftMaterial,
                    false,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                    $"{prefix}.library.upper_gallery.left_rail_baluster.{i}");

                var rightHeight = past ? 0.62f : (i == 1 ? 0.48f : 0.58f);
                var rightMaterial = past ? trim : (i == 1 ? materials.Dust : trim);
                CreateLandmarkCube(
                    $"{prefix}_Library_UpperGallery_RightRail_Baluster_{i}",
                    root,
                    c + new Vector3(4.84f, 2.44f, 0.10f + rightRailZs[i]),
                    new Vector3(0.07f, rightHeight, 0.07f),
                    Quaternion.identity,
                    rightMaterial,
                    false,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                    $"{prefix}.library.upper_gallery.right_rail_baluster.{i}");

                var backHeight = past ? 0.62f : (i == 3 ? 0.44f : 0.58f);
                var backMaterial = past ? trim : (i == 3 ? materials.Dust : trim);
                CreateLandmarkCube(
                    $"{prefix}_Library_UpperGallery_BackRail_Baluster_{i}",
                    root,
                    c + new Vector3(backRailXs[i], 2.44f, 7.02f),
                    new Vector3(0.07f, backHeight, 0.07f),
                    Quaternion.identity,
                    backMaterial,
                    false,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                    $"{prefix}.library.upper_gallery.back_rail_baluster.{i}");
            }

            var pilasterXs = new[] { -3.72f, 0f, 3.72f };
            for (var i = 0; i < pilasterXs.Length; i++)
            {
                CreateLandmarkCube(
                    $"{prefix}_Library_UpperGallery_BackWall_Pilaster_{i}",
                    root,
                    c + new Vector3(pilasterXs[i], 1.80f, 7.40f),
                    new Vector3(0.10f, 0.72f, 0.04f),
                    Quaternion.identity,
                    past ? (i == 1 ? wood : trim) : materials.Dust,
                    false,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                    $"{prefix}.library.upper_gallery.back_wall_pilaster.{i}");
            }

            var wallShadowStripScale = past ? new Vector3(0.08f, 0.76f, 0.04f) : new Vector3(0.06f, 0.66f, 0.035f);
            var wallShadowStripMaterial = past ? trim : materials.Dust;
            CreateLandmarkCube(
                $"{prefix}_Library_UpperGallery_LeftWall_ShadowStrip",
                root,
                c + new Vector3(-5.40f, 1.86f, 1.48f),
                wallShadowStripScale,
                Quaternion.identity,
                wallShadowStripMaterial,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.upper_gallery.left_wall_shadow_strip");
            CreateLandmarkCube(
                $"{prefix}_Library_UpperGallery_RightWall_ShadowStrip",
                root,
                c + new Vector3(5.40f, 1.86f, 1.48f),
                wallShadowStripScale,
                Quaternion.identity,
                wallShadowStripMaterial,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.upper_gallery.right_wall_shadow_strip");
        }

        private static void CreateLibraryUpperGallerySupportPolish(Transform root, string prefix, bool past, Materials materials, Vector3 c, Material wood, Material trim)
        {
            var undersideShadowMaterial = past ? materials.Shadow : materials.Dust;
            var undersideDustMaterial = materials.Dust;
            var postMaterial = past ? wood : materials.Dust;
            var railMaterial = past ? trim : materials.Dust;
            var postY = past ? 1.55f : 1.42f;
            var postScale = past ? new Vector3(0.08f, 1.30f, 0.08f) : new Vector3(0.045f, 0.96f, 0.045f);
            var sideRailScale = past ? new Vector3(0.045f, 0.030f, 9.10f) : new Vector3(0.030f, 0.024f, 9.00f);
            var backRailScale = past ? new Vector3(8.72f, 0.030f, 0.045f) : new Vector3(8.62f, 0.024f, 0.030f);

            CreateNonArrivalLandmarkCube(
                $"{prefix}_Library_UpperGallerySupport_LeftUndersideShadowA",
                root,
                c + new Vector3(-4.18f, 1.96f, 0.10f),
                new Vector3(1.30f, 0.035f, 9.50f),
                Quaternion.identity,
                undersideShadowMaterial,
                $"{prefix}.library.upper_gallery_support.left_underside_shadow_a");
            CreateNonArrivalLandmarkCube(
                $"{prefix}_Library_UpperGallerySupport_RightUndersideShadowA",
                root,
                c + new Vector3(4.18f, 1.96f, 0.10f),
                new Vector3(1.30f, 0.035f, 9.50f),
                Quaternion.identity,
                undersideShadowMaterial,
                $"{prefix}.library.upper_gallery_support.right_underside_shadow_a");
            CreateNonArrivalLandmarkCube(
                $"{prefix}_Library_UpperGallerySupport_BackGalleryUndersideShadowA",
                root,
                c + new Vector3(0.00f, 1.96f, 6.45f),
                new Vector3(8.60f, 0.035f, 0.90f),
                Quaternion.identity,
                undersideDustMaterial,
                $"{prefix}.library.upper_gallery_support.back_gallery_underside_shadow_a");

            CreateNonArrivalLandmarkCube(
                $"{prefix}_Library_UpperGallerySupport_LeftFrontPostA",
                root,
                c + new Vector3(-4.84f, postY, -4.56f),
                postScale,
                Quaternion.identity,
                postMaterial,
                $"{prefix}.library.upper_gallery_support.left_front_post_a");
            CreateNonArrivalLandmarkCube(
                $"{prefix}_Library_UpperGallerySupport_LeftBackPostA",
                root,
                c + new Vector3(-4.84f, postY, 4.54f),
                postScale,
                Quaternion.identity,
                postMaterial,
                $"{prefix}.library.upper_gallery_support.left_back_post_a");
            CreateNonArrivalLandmarkCube(
                $"{prefix}_Library_UpperGallerySupport_RightFrontPostA",
                root,
                c + new Vector3(4.84f, postY, -4.56f),
                postScale,
                Quaternion.identity,
                postMaterial,
                $"{prefix}.library.upper_gallery_support.right_front_post_a");
            CreateNonArrivalLandmarkCube(
                $"{prefix}_Library_UpperGallerySupport_RightBackPostA",
                root,
                c + new Vector3(4.84f, postY, 4.54f),
                postScale,
                Quaternion.identity,
                postMaterial,
                $"{prefix}.library.upper_gallery_support.right_back_post_a");

            CreateNonArrivalLandmarkCube(
                $"{prefix}_Library_UpperGallerySupport_LeftRailTopHighlightA",
                root,
                c + new Vector3(-4.84f, 2.565f, 0.10f),
                sideRailScale,
