        private static void ValidateAtmosphereParticleSystem(string objectName, int expectedLayer, Material expectedMaterial)
        {
            var atmosphere = FindSceneObjectIncludingInactive(objectName);
            if (atmosphere == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing atmosphere object {objectName}.");
            }

            var system = atmosphere.GetComponent<ParticleSystem>();
            var renderer = atmosphere.GetComponent<ParticleSystemRenderer>();
            if (system == null || renderer == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must have ParticleSystem and ParticleSystemRenderer components.");
            }

            if (atmosphere.layer != expectedLayer)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must be on layer {expectedLayer}, but was {atmosphere.layer}.");
            }

            var main = system.main;
            var emission = system.emission;
            if (main.maxParticles > 80 ||
                !main.loop ||
                !main.prewarm ||
                main.duration <= 0f ||
                main.startLifetime.constant <= 0f ||
                main.startSpeed.constant <= 0f ||
                main.startSize.constant <= 0f ||
                emission.rateOverTime.constant <= 0f)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must be a looping prewarmed atmosphere emitter with nonzero timing values and maxParticles <= 80.");
            }

            if (renderer.sharedMaterial != expectedMaterial ||
                renderer.shadowCastingMode != ShadowCastingMode.Off ||
                renderer.receiveShadows)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must use the generated atmosphere material with shadows disabled.");
            }
        }

        private static void ValidateGeneratedRepeatTextureAsset(string textureId, int minWidth, int minHeight, int minimumDistinctColors)
        {
            var path = $"{TextureDirectory}/FastVS_House_{textureId}.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing generated texture asset {path}.");
            }

            if (texture.width < minWidth || texture.height < minHeight)
            {
                throw new InvalidOperationException($"House slice validation failed: {textureId} must be at least {minWidth}x{minHeight}, but was {texture.width}x{texture.height}.");
            }

            if (texture.filterMode != FilterMode.Point || texture.wrapMode != TextureWrapMode.Repeat)
            {
                throw new InvalidOperationException($"House slice validation failed: {textureId} must use point filtering and repeat wrap.");
            }

            if (CountDistinctOpaqueColors(texture) < minimumDistinctColors)
            {
                throw new InvalidOperationException($"House slice validation failed: {textureId} must contain enough opaque color variation.");
            }
        }

        private static void ValidateGeneratedSurfaceMaterialTexture(string materialId, string textureId)
        {
            var materialPath = $"{MaterialDirectory}/FastVS_House_{materialId}.mat";
            var texturePath = $"{TextureDirectory}/FastVS_House_{textureId}.asset";
            var material = AssetDatabase.LoadAssetAtPath<Material>(materialPath);
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(texturePath);
            if (material == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing material asset {materialPath}.");
            }

            if (texture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing texture asset {texturePath}.");
            }

            if (!MaterialUsesTexture(material, texture))
            {
                throw new InvalidOperationException($"House slice validation failed: {materialId} must reference {textureId}.");
            }
        }

        private static void ValidateCharacterContactShadowTextureMetrics(string context)
        {
            var path = $"{TextureDirectory}/FastVS_House_character_contact_shadow.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing character contact shadow texture asset {path} for {context}.");
            }

            ValidateCharacterContactShadowTextureMetrics(texture, context);
        }

        private static void ValidateCharacterContactShadowTextureMetrics(Texture2D texture, string context)
        {
            if (texture.width != 96 || texture.height != 48)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} must keep the character contact shadow texture at exactly 96x48, but was {texture.width}x{texture.height}.");
            }

            if (texture.filterMode != FilterMode.Bilinear)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} must keep the character contact shadow texture bilinear.");
            }

            if (texture.wrapMode != TextureWrapMode.Clamp)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} must keep the character contact shadow texture clamp-wrapped.");
            }

            var centerX = texture.width / 2;
            var centerY = texture.height / 2;
            var leftFootX = Mathf.Clamp(Mathf.RoundToInt(texture.width * 0.37f), 0, texture.width - 1);
            var rightFootX = Mathf.Clamp(Mathf.RoundToInt(texture.width * 0.63f), 0, texture.width - 1);
            var footY = Mathf.Clamp(Mathf.RoundToInt(texture.height * 0.60f), 0, texture.height - 1);

            var centerAlpha = texture.GetPixel(centerX, centerY).a;
            var leftEdgeAlpha = texture.GetPixel(0, centerY).a;
            var rightEdgeAlpha = texture.GetPixel(texture.width - 1, centerY).a;
            var topEdgeAlpha = texture.GetPixel(centerX, texture.height - 1).a;
            var bottomEdgeAlpha = texture.GetPixel(centerX, 0).a;
            var leftFootAlpha = texture.GetPixel(leftFootX, footY).a;
            var rightFootAlpha = texture.GetPixel(rightFootX, footY).a;
            var topLeftCornerAlpha = texture.GetPixel(0, texture.height - 1).a;
            var topRightCornerAlpha = texture.GetPixel(texture.width - 1, texture.height - 1).a;
            var bottomLeftCornerAlpha = texture.GetPixel(0, 0).a;
            var bottomRightCornerAlpha = texture.GetPixel(texture.width - 1, 0).a;

            var maxAlpha = 0f;
            foreach (var pixel in texture.GetPixels32())
            {
                maxAlpha = Mathf.Max(maxAlpha, pixel.a / 255f);
            }

            if (centerAlpha < 0.18f || centerAlpha > 0.30f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} center alpha {centerAlpha:0.000} is outside the 0.18-0.30 range.");
            }

            if (leftEdgeAlpha > 0.02f || rightEdgeAlpha > 0.02f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} edge alpha must stay at or below 0.020. left={leftEdgeAlpha:0.000}, right={rightEdgeAlpha:0.000}.");
            }

            if (topEdgeAlpha > 0.03f || bottomEdgeAlpha > 0.03f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} top/bottom edge alpha must stay soft. top={topEdgeAlpha:0.000}, bottom={bottomEdgeAlpha:0.000}.");
            }

            if (leftFootAlpha < 0.24f || leftFootAlpha > 0.40f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} left foot alpha {leftFootAlpha:0.000} is outside the 0.24-0.40 range.");
            }

            if (rightFootAlpha < 0.24f || rightFootAlpha > 0.40f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} right foot alpha {rightFootAlpha:0.000} is outside the 0.24-0.40 range.");
            }

            if (maxAlpha < 0.30f || maxAlpha > 0.42f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} max alpha {maxAlpha:0.000} is outside the 0.30-0.42 range.");
            }

            if (topLeftCornerAlpha > 0.01f || topRightCornerAlpha > 0.01f || bottomLeftCornerAlpha > 0.01f || bottomRightCornerAlpha > 0.01f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} corner alpha must stay near transparent. tl={topLeftCornerAlpha:0.000}, tr={topRightCornerAlpha:0.000}, bl={bottomLeftCornerAlpha:0.000}, br={bottomRightCornerAlpha:0.000}.");
            }
        }

        private static void ValidateHd2dCharacterGroundBounceTexture()
        {
