                throw new InvalidOperationException($"House slice validation failed: {objectName} must be parented under {expectedParentName}.");
            }

            var landmark = sceneObject.GetComponent<TimeWindowPairedSpaceLandmark>();
            if (landmark == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep a TimeWindowPairedSpaceLandmark.");
            }

            var landmarkSerialized = new SerializedObject(landmark);
            var kindProperty = landmarkSerialized.FindProperty("kind");
            if (kindProperty == null ||
                kindProperty.propertyType != SerializedPropertyType.Enum ||
                kindProperty.enumValueIndex != Convert.ToInt32(TimeWindowPairedSpaceLandmarkKind.PropOrFeature))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must use TimeWindowPairedSpaceLandmarkKind.PropOrFeature.");
            }

            if (sceneObject.transform.localScale.y > maxScaleY)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must stay low to the ground.");
            }

            var materialName = renderer.sharedMaterial.name ?? string.Empty;
            if (materialName.IndexOf(expectedMaterialToken, StringComparison.OrdinalIgnoreCase) < 0)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must use a material containing {expectedMaterialToken} in its name.");
            }
        }

        private static void ValidateGeneratedTextureExactSize(string textureId, int expectedWidth, int expectedHeight)
        {
            var path = $"{TextureDirectory}/FastVS_House_{textureId}.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing generated texture asset {path}.");
            }

            if (texture.width != expectedWidth || texture.height != expectedHeight)
            {
                throw new InvalidOperationException($"House slice validation failed: {textureId} must be exactly {expectedWidth}x{expectedHeight}, but was {texture.width}x{texture.height}.");
            }
        }

        private static float SampleTextureLuminance(Texture2D texture, int x, int y)
        {
            var clampedX = Mathf.Clamp(x, 0, texture.width - 1);
            var clampedY = Mathf.Clamp(y, 0, texture.height - 1);
            return CalculateLuminance(texture.GetPixel(clampedX, clampedY));
        }

        private static float CalculateLuminance(Color color)
        {
            return (0.2126f * color.r) + (0.7152f * color.g) + (0.0722f * color.b);
        }

        private static float SoftBand01(float value, float center, float halfWidth)
        {
            return 1f - Mathf.Clamp01(Mathf.Abs(value - center) / halfWidth);
        }

        private static void ValidateTextureLuminanceContrast(string textureId, Vector2Int a, Vector2Int b, float minDelta, string label)
        {
            var path = $"{TextureDirectory}/FastVS_House_{textureId}.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing generated texture asset {path}.");
            }

            var colorA = texture.GetPixel(a.x, a.y);
            var colorB = texture.GetPixel(b.x, b.y);
            var lumaA = 0.2126f * colorA.r + 0.7152f * colorA.g + 0.0722f * colorA.b;
            var lumaB = 0.2126f * colorB.r + 0.7152f * colorB.g + 0.0722f * colorB.b;
            var delta = Mathf.Abs(lumaA - lumaB);
            if (delta < minDelta)
            {
                throw new InvalidOperationException($"House slice validation failed: {label} must have at least {minDelta:0.000} luminance contrast, but delta was {delta:0.000}.");
            }
        }

        private static void ValidateTextureLuminanceRange(string textureId, float minRange, string label)
        {
            var path = $"{TextureDirectory}/FastVS_House_{textureId}.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing generated texture asset {path}.");
            }

            var minLuma = float.MaxValue;
            var maxLuma = float.MinValue;
            foreach (var color in texture.GetPixels())
            {
                if (color.a <= 0.03f)
                {
                    continue;
                }

                var luma = 0.2126f * color.r + 0.7152f * color.g + 0.0722f * color.b;
                minLuma = Mathf.Min(minLuma, luma);
                maxLuma = Mathf.Max(maxLuma, luma);
            }

            if (minLuma == float.MaxValue || maxLuma - minLuma < minRange)
            {
                throw new InvalidOperationException($"House slice validation failed: {label} must have at least {minRange:0.000} luminance range, but range was {(maxLuma - minLuma):0.000}.");
            }
        }

        private static void ValidateBookSpinePaletteSamples(bool bookshelfFront, float maxSaturation, float maxValue)
        {
            var label = bookshelfFront ? "bookshelf front" : "book spine";
            var samples = bookshelfFront
                ? new (int columnIndex, int rowIndex, int seed)[]
                {
                    (0, 0, 131),
                    (2, 1, 131),
                    (4, 0, 131),
                    (7, 2, 131),
                    (10, 1, 131),
                    (13, 2, 131)
                }
                : new (int columnIndex, int rowIndex, int seed)[]
                {
                    (0, 0, 109),
                    (2, 1, 109),
                    (4, 0, 109),
                    (7, 1, 109),
                    (10, 0, 109),
                    (13, 2, 109)
                };

            foreach (var sample in samples)
            {
                var color = PickBookSpineColor(sample.columnIndex, sample.rowIndex, sample.seed, bookshelfFront);
                Color.RGBToHSV(color, out _, out var saturation, out var value);
                if (saturation > maxSaturation || value > maxValue)
                {
                    throw new InvalidOperationException($"House slice validation failed: {label} palette sample {sample.columnIndex}/{sample.rowIndex} is too vivid. saturation={saturation:0.000}, value={value:0.000}");
                }
            }
        }

        private static void ValidateBookSpineWidthVariation(bool bookshelfFront)
        {
            var widths = new HashSet<int>();
            for (var index = 0; index < 16; index++)
            {
                var width = GetBookSpineWidth(index, index % 3, bookshelfFront ? 131 : 109, bookshelfFront);
                if (width < 5 || width > 14)
                {
                    throw new InvalidOperationException($"House slice validation failed: {(bookshelfFront ? "bookshelf front" : "book spine")} width {width} is outside the expected 5-14 px range.");
                }

                widths.Add(width);
            }

            if (widths.Count < 4)
            {
                throw new InvalidOperationException($"House slice validation failed: {(bookshelfFront ? "bookshelf front" : "book spine")} widths do not vary enough to avoid barcode-like repetition.");
            }
        }

        private static bool MaterialUsesTexture(Material material, Texture2D texture)
        {
            var matched = false;

            if (material.HasProperty("_BaseMap"))
            {
                var baseMap = material.GetTexture("_BaseMap") as Texture2D;
                if (baseMap == texture)
                {
                    matched = true;
                }
            }

            if (material.HasProperty("_MainTex"))
            {
                var mainTex = material.GetTexture("_MainTex") as Texture2D;
                if (mainTex == texture)
                {
                    matched = true;
                }
            }

            return matched;
        }

        private static int CountDistinctOpaqueColors(Texture2D texture)
        {
            var distinct = new HashSet<int>();
            var pixels = texture.GetPixels32();
            for (var index = 0; index < pixels.Length; index++)
            {
                var pixel = pixels[index];
                if (pixel.a < 255)
                {
                    continue;
                }

                distinct.Add((pixel.r << 24) | (pixel.g << 16) | (pixel.b << 8) | pixel.a);
            }

            return distinct.Count;
        }

        private static void ValidateMaterialSmoothness(string materialPath)
        {
            var material = AssetDatabase.LoadAssetAtPath<Material>(materialPath);
            if (material == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing material asset {materialPath}.");
            }

            if (material.HasProperty("_Smoothness") && material.GetFloat("_Smoothness") > 0.20f)
            {
                throw new InvalidOperationException($"House slice validation failed: {materialPath} must remain matte with _Smoothness <= 0.20.");
            }
        }

        private static void ValidateSurfaceRampMaterials()
        {
            foreach (var materialPath in new[]
            {
                "Assets/Art/Materials/FastVS/HouseSlice/FastVS_House_current_exterior_wall.mat",
                "Assets/Art/Materials/FastVS/HouseSlice/FastVS_House_current_ground.mat",
                "Assets/Art/Materials/FastVS/HouseSlice/FastVS_House_current_path.mat",
                "Assets/Art/Materials/FastVS/HouseSlice/FastVS_House_current_roof.mat",
                "Assets/Art/Materials/FastVS/HouseSlice/FastVS_House_past_wood_floor.mat",
                "Assets/Art/Materials/FastVS/HouseSlice/FastVS_House_past_interior_wall.mat",
                "Assets/Art/Materials/FastVS/HouseSlice/FastVS_House_past_exterior_wall.mat",
                "Assets/Art/Materials/FastVS/HouseSlice/FastVS_House_past_furniture.mat",
