        private static Texture2D EnsureHd2dOutdoorOcclusionGradientTexture()
        {
            return EnsureGeneratedTexture(
                "hd2d_outdoor_occlusion_gradient_soft",
                192,
                128,
                FilterMode.Bilinear,
                (x, y) =>
                {
                    var u = x / 191f;
                    var v = y / 127f;
                    var centerFeather = SmoothFade01(0f, 0.12f, u) * SmoothFade01(0f, 0.12f, 1f - u);
                    var upperBand = Mathf.Pow(v, 1.45f);
                    var midBand = Mathf.Clamp01((v - 0.18f) / 0.62f);
                    var alpha = (upperBand * 0.30f) + (midBand * 0.10f) + (centerFeather * upperBand * 0.08f);
                    alpha = Mathf.Clamp(alpha, 0f, 0.357f);
                    return new Color(0.13f, 0.14f, 0.17f, alpha);
                });
        }

        private static Texture2D EnsureHd2dOutdoorWarmStageLightTexture()
        {
            return EnsureGeneratedTexture(
                "hd2d_outdoor_warm_stage_light_soft",
                192,
                128,
                FilterMode.Bilinear,
                (x, y) =>
                {
                    var u = (x / 191f) * 2f - 1f;
                    var v = (y / 127f) * 2f - 1f;
                    var coreDx = u / 0.74f;
                    var coreDy = (v + 0.14f) / 0.50f;
                    var haloDx = u / 0.96f;
                    var haloDy = (v + 0.18f) / 0.74f;
                    var core = Mathf.Clamp01(1f - Mathf.Sqrt((coreDx * coreDx) + (coreDy * coreDy)));
                    var halo = Mathf.Clamp01(1f - Mathf.Sqrt((haloDx * haloDx) + (haloDy * haloDy)));
                    var lowerSkirt = Mathf.Clamp01(1f - Mathf.Sqrt((u * u * 1.10f) + (((v - 0.52f) / 0.36f) * ((v - 0.52f) / 0.36f))));
                    var alpha = (core * 0.28f) + (halo * 0.14f) + (lowerSkirt * 0.04f);
                    alpha = Mathf.Clamp(alpha, 0f, 0.38f);
                    return new Color(1.0f, 0.82f, 0.48f, alpha);
                });
        }

        private static Material EnsureHd2dOutdoorScenicBackdropMaterial(string id, bool past, FastVsHouseArea area, string layer)
        {
            var material = FlatMaterial(id, Color.white, true, FastVsHd2dMaterialRole.OverlayGlow);
            ConfigureTransparentUnlitMaterial(material, 2994);
            var texture = EnsureHd2dOutdoorScenicBackdropTexture(id, past, area, layer);
            AssignMaterialTexture(material, texture, Vector2.one);

            Color tint;
            if (layer == "composition_sky")
            {
                tint = area == FastVsHouseArea.Exterior
                    ? new Color(1f, 1f, 1f, past ? 0.98f : 0.96f)
                    : new Color(1f, 1f, 1f, past ? 0.44f : 0.40f);
            }
            else if (layer == "composition_horizon")
            {
                tint = new Color(1f, 1f, 1f, past ? 0.54f : 0.48f);
            }
            else if (layer == "composition_edge_wrap")
            {
                tint = area == FastVsHouseArea.Exterior
                    ? new Color(1f, 1f, 1f, past ? 0.075f : 0.065f)
                    : new Color(1f, 1f, 1f, past ? 0.32f : 0.28f);
            }
            else if (layer == "sky_curtain")
            {
                tint = new Color(1f, 1f, 1f, past ? 0.30f : 0.28f);
            }
            else if (layer == "sky_wrap")
            {
                tint = new Color(1f, 1f, 1f, past ? 0.10f : 0.08f);
            }
            else
            {
                tint = new Color(1f, 1f, 1f, past ? 0.42f : 0.38f);
            }
            if (material.HasProperty("_BaseColor"))
            {
                material.SetColor("_BaseColor", tint);
            }

            if (material.HasProperty("_Color"))
            {
                material.SetColor("_Color", tint);
            }

            EditorUtility.SetDirty(material);
            AssetDatabase.SaveAssets();
            return material;
        }

