        private static void ConfigureTransparentUnlitMaterial(Material material, int renderQueue)
        {
            ConfigureTransparentMaterial(material, renderQueue, "Universal Render Pipeline/Unlit");
        }

        private static void ConfigureTransparentParticleMaterial(Material material, int renderQueue)
        {
            ConfigureTransparentMaterial(material, renderQueue, "Universal Render Pipeline/Particles/Unlit", "Universal Render Pipeline/Unlit");
        }

        private static void ConfigureTransparentMaterial(Material material, int renderQueue, params string[] shaderNames)
        {
            Shader shader = null;
            foreach (var shaderName in shaderNames)
            {
                shader = Shader.Find(shaderName);
                if (shader != null)
                {
                    break;
                }
            }

            if (shader == null)
            {
                throw new InvalidOperationException($"Required shader not found: {string.Join(", ", shaderNames)}");
            }

            material.shader = shader;
            material.doubleSidedGI = true;

            if (material.HasProperty("_Surface"))
            {
                material.SetFloat("_Surface", 1f);
            }

            if (material.HasProperty("_Blend"))
            {
                material.SetFloat("_Blend", 0f);
            }

            if (material.HasProperty("_SrcBlend"))
            {
                material.SetFloat("_SrcBlend", 5f);
            }

            if (material.HasProperty("_DstBlend"))
            {
                material.SetFloat("_DstBlend", 10f);
            }

            if (material.HasProperty("_ZWrite"))
            {
                material.SetFloat("_ZWrite", 0f);
            }

            if (material.HasProperty("_ZTest"))
            {
                material.SetFloat("_ZTest", (float)CompareFunction.LessEqual);
            }

            if (material.HasProperty("_Cull"))
            {
                material.SetFloat("_Cull", 0f);
            }

            if (material.HasProperty("_AlphaClip"))
            {
                material.SetFloat("_AlphaClip", 0f);
            }

            if (material.HasProperty("_QueueControl"))
            {
                material.SetFloat("_QueueControl", 1f);
            }

            if (material.HasProperty("_QueueOffset"))
            {
                material.SetFloat("_QueueOffset", renderQueue - 3000f);
            }

            if (material.HasProperty("_SrcBlendAlpha"))
            {
                material.SetFloat("_SrcBlendAlpha", 1f);
            }

            if (material.HasProperty("_DstBlendAlpha"))
            {
                material.SetFloat("_DstBlendAlpha", 10f);
            }

            material.SetOverrideTag("RenderType", "Transparent");
            material.SetShaderPassEnabled("DepthOnly", false);
            material.SetShaderPassEnabled("SHADOWCASTER", false);
            material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
            material.renderQueue = renderQueue;
            EditorUtility.SetDirty(material);
        }

        private static Texture2D EnsureHd2dAtmosphereParticleTexture()
        {
            return EnsureGeneratedTexture(
                "hd2d_atmosphere_particle_soft",
                64,
                64,
                FilterMode.Bilinear,
                (x, y) =>
                {
                    var centeredX = ((x + 0.5f) / 64f) * 2f - 1f;
                    var centeredY = ((y + 0.5f) / 64f) * 2f - 1f;
                    var distance = Mathf.Sqrt((centeredX * centeredX) + (centeredY * centeredY));
                    var core = Mathf.Clamp01(1f - distance);
                    var alpha = core * core * 0.95f;
                    var tone = 0.96f + (core * 0.04f);
                    return new Color(tone, tone, tone, alpha);
                });
        }

        private static Texture2D EnsureHd2dOutdoorScenicBackdropTexture(string id, bool past, FastVsHouseArea area, string layer)
        {
            var path = $"{TextureDirectory}/FastVS_House_{id}.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture != null && (texture.width != 160 || texture.height != 96 || texture.format != TextureFormat.RGBA32 || TextureAlphaChannelIsEmpty(texture)))
            {
                AssetDatabase.DeleteAsset(path);
                texture = null;
            }

            if (texture == null)
            {
                texture = new Texture2D(160, 96, TextureFormat.RGBA32, false);
                AssetDatabase.CreateAsset(texture, path);
            }

            texture.name = $"FastVS_House_{id}";
            texture.filterMode = FilterMode.Bilinear;
            texture.wrapMode = TextureWrapMode.Clamp;

            var seed = (past ? 193 : 59) + (area == FastVsHouseArea.Exterior ? 17 : 71) + layer.Length;
            var pixels = new Color32[texture.width * texture.height];
            for (var y = 0; y < texture.height; y++)
            {
                var v = y / 95f;
                for (var x = 0; x < texture.width; x++)
                {
                    var u = x / 159f;
                    var edgeFade = SmoothFade01(0f, 0.06f, u) * SmoothFade01(0f, 0.06f, 1f - u) * SmoothFade01(0f, 0.05f, v) * SmoothFade01(0f, 0.05f, 1f - v);
                    var wobble = (Mathf.Sin((u * 8.0f) + (seed * 0.13f)) * 0.035f) +
                                 (Mathf.Sin((u * 18.0f) + (seed * 0.07f)) * 0.014f);
                    Color tint;
                    float alpha;

                    if (layer == "composition_sky")
                    {
                        var skyBlend = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((v - 0.06f) / 0.88f));
                        var cloudDriftA = (Mathf.Sin((u * 4.4f) + (seed * 0.21f)) * 0.014f) + (Mathf.Sin((u * 9.6f) + (seed * 0.09f)) * 0.006f);
                        var cloudCenterA = 0.56f + cloudDriftA;
                        var cloudBandA = Mathf.Exp(-Mathf.Pow((v - cloudCenterA) / 0.032f, 2f));
                        cloudBandA *= Mathf.Clamp01(0.84f - Mathf.Abs(u - 0.5f) * 1.55f);

                        var cloudDriftB = (Mathf.Sin((u * 7.8f) + (seed * 0.17f)) * 0.010f) + (Mathf.Sin((u * 14.1f) + (seed * 0.11f)) * 0.004f);
                        var cloudCenterB = 0.77f + cloudDriftB;
                        var cloudBandB = Mathf.Exp(-Mathf.Pow((v - cloudCenterB) / 0.024f, 2f));
                        cloudBandB *= Mathf.Clamp01(0.74f - Mathf.Abs(u - 0.5f) * 1.18f);

                        Color lowerColor;
                        Color upperColor;
                        Color hazeColor;
                        Color cloudColor;
                        if (area == FastVsHouseArea.Exterior)
                        {
                            lowerColor = past ? new Color(0.56f, 0.49f, 0.42f, 1f) : new Color(0.30f, 0.39f, 0.49f, 1f);
                            upperColor = past ? new Color(0.80f, 0.70f, 0.58f, 1f) : new Color(0.58f, 0.69f, 0.82f, 1f);
                            hazeColor = past ? new Color(0.70f, 0.60f, 0.50f, 1f) : new Color(0.52f, 0.60f, 0.67f, 1f);
                            cloudColor = past ? new Color(0.88f, 0.79f, 0.70f, 1f) : new Color(0.74f, 0.82f, 0.90f, 1f);
                        }
                        else
                        {
                            lowerColor = past ? new Color(0.52f, 0.46f, 0.39f, 1f) : new Color(0.28f, 0.36f, 0.46f, 1f);
                            upperColor = past ? new Color(0.77f, 0.67f, 0.56f, 1f) : new Color(0.55f, 0.66f, 0.79f, 1f);
                            hazeColor = past ? new Color(0.66f, 0.57f, 0.47f, 1f) : new Color(0.48f, 0.56f, 0.64f, 1f);
                            cloudColor = past ? new Color(0.84f, 0.76f, 0.66f, 1f) : new Color(0.70f, 0.79f, 0.86f, 1f);
                        }

                        tint = Color.Lerp(lowerColor, upperColor, skyBlend);
                        tint = Color.Lerp(tint, hazeColor, Mathf.Clamp01((1f - Mathf.Abs(v - 0.42f) * 2.2f) * 0.24f));
                        tint = Color.Lerp(tint, cloudColor, Mathf.Clamp01((cloudBandA + cloudBandB) * 0.25f));
                        if (area == FastVsHouseArea.Exterior)
                        {
                            alpha = ((0.78f + skyBlend * 0.14f) + (cloudBandA * 0.08f) + (cloudBandB * 0.05f)) * edgeFade;
                            alpha = Mathf.Clamp(alpha, 0f, past ? 0.98f : 0.96f);
                        }
                        else
                        {
                            alpha = ((0.20f + skyBlend * 0.34f) + (cloudBandA * 0.16f) + (cloudBandB * 0.10f)) * edgeFade;
                            alpha = Mathf.Clamp(alpha, 0f, past ? 0.58f : 0.52f);
                        }
                    }
                    else if (layer == "composition_horizon")
                    {
                        var horizonCore = area == FastVsHouseArea.Exterior
                            ? Mathf.Exp(-Mathf.Pow((v - (0.48f + wobble * 0.38f)) / 0.11f, 2f))
                            : Mathf.Exp(-Mathf.Pow((v - (0.50f + wobble * 0.34f)) / 0.10f, 2f));
                        var skylineSteps = area == FastVsHouseArea.Exterior
                            ? Mathf.Clamp01(1f - Mathf.Abs(Mathf.Sin((u * 7.8f) + (seed * 0.17f))) * 0.52f)
                            : Mathf.Clamp01(1f - Mathf.Abs(Mathf.Sin((u * 10.5f) + (seed * 0.15f))) * 0.46f);
                        var silhouette = Mathf.Clamp01((horizonCore * 0.82f) + (skylineSteps * 0.18f));

                        if (area == FastVsHouseArea.Exterior)
                        {
                            tint = past ? new Color(0.43f, 0.37f, 0.31f, 1f) : new Color(0.23f, 0.30f, 0.24f, 1f);
                        }
                        else
                        {
                            tint = past ? new Color(0.40f, 0.33f, 0.28f, 1f) : new Color(0.25f, 0.27f, 0.29f, 1f);
                        }

                        tint = Color.Lerp(tint, past ? new Color(0.68f, 0.59f, 0.48f, 1f) : new Color(0.50f, 0.56f, 0.60f, 1f), Mathf.Clamp01(1f - silhouette));
                        alpha = ((0.26f + silhouette * 0.44f) + horizonCore * 0.08f) * edgeFade;
                        alpha = Mathf.Clamp(alpha, 0f, past ? 0.62f : 0.56f);
                    }
                    else if (layer == "composition_edge_wrap")
                    {
                        var verticalBand = SmoothFade01(0.0f, 0.16f, v) * SmoothFade01(1f, 0.72f, v);
                        var edgeBand = Mathf.Clamp01(1f - Mathf.Min(Mathf.Abs(u - 0.24f), Mathf.Abs(u - 0.76f)) * 4.5f);
                        var wrapCore = Mathf.Clamp01(verticalBand * (0.42f + (edgeBand * 0.58f)));
                        if (area == FastVsHouseArea.Exterior)
                        {
                            tint = past ? new Color(0.59f, 0.52f, 0.44f, 1f) : new Color(0.43f, 0.53f, 0.62f, 1f);
                            tint = Color.Lerp(tint, past ? new Color(0.76f, 0.68f, 0.58f, 1f) : new Color(0.64f, 0.73f, 0.84f, 1f), wrapCore * 0.58f);
                            alpha = Mathf.Clamp(((0.025f + wrapCore * 0.070f) + (edgeBand * 0.018f)) * edgeFade, 0f, past ? 0.12f : 0.10f);
                        }
                        else
                        {
                            tint = past ? new Color(0.49f, 0.43f, 0.37f, 1f) : new Color(0.31f, 0.39f, 0.46f, 1f);
                            tint = Color.Lerp(tint, past ? new Color(0.70f, 0.62f, 0.54f, 1f) : new Color(0.55f, 0.64f, 0.72f, 1f), wrapCore * 0.46f);
                            alpha = Mathf.Clamp(((0.12f + wrapCore * 0.26f) + (edgeBand * 0.06f)) * edgeFade, 0f, past ? 0.34f : 0.30f);
                        }
                    }
                    else if (layer == "sky_curtain" || layer == "sky_wrap")
                    {
                        var isWrap = layer == "sky_wrap";
                        var lower = past
                            ? (isWrap ? new Color(0.58f, 0.52f, 0.43f, 1f) : new Color(0.50f, 0.43f, 0.35f, 1f))
                            : (isWrap ? new Color(0.44f, 0.52f, 0.60f, 1f) : new Color(0.35f, 0.43f, 0.52f, 1f));
                        var upper = past
                            ? (isWrap ? new Color(0.70f, 0.62f, 0.51f, 1f) : new Color(0.64f, 0.55f, 0.45f, 1f))
                            : (isWrap ? new Color(0.58f, 0.66f, 0.75f, 1f) : new Color(0.48f, 0.57f, 0.68f, 1f));
                        var cloud = Mathf.Exp(-Mathf.Pow((v - (0.68f + wobble)) / 0.075f, 2f)) * Mathf.Clamp01(0.75f - Mathf.Abs(u - 0.5f));
                        tint = Color.Lerp(lower, upper, Mathf.SmoothStep(0f, 1f, v));
                        tint = Color.Lerp(tint, Color.white, cloud * 0.12f);
                        alpha = (isWrap ? 0.055f : 0.22f) + (cloud * (isWrap ? 0.035f : 0.15f));
                        alpha *= edgeFade;
                    }
                    else if (layer == "low_haze_band")
                    {
                        var hazeCore = Mathf.Exp(-Mathf.Pow((v - (0.52f + wobble * 0.45f)) / 0.20f, 2f));
                        tint = past ? new Color(0.56f, 0.49f, 0.39f, 1f) : new Color(0.48f, 0.55f, 0.56f, 1f);
                        alpha = (0.24f + hazeCore * 0.34f) * edgeFade;
                    }
                    else if (layer == "distant_tree_line")
                    {
                        var canopy = Mathf.Clamp01(1f - Mathf.Abs(v - (0.48f + wobble)) * 5.5f);
                        tint = past ? new Color(0.32f, 0.36f, 0.25f, 1f) : new Color(0.21f, 0.30f, 0.22f, 1f);
                        alpha = (0.10f + canopy * 0.55f) * edgeFade;
                    }
                    else
                    {
                        var roofStep = Mathf.Clamp01(1f - Mathf.Abs(v - (0.48f + Mathf.Sign(Mathf.Sin(u * 28f + seed)) * 0.05f)) * 6.0f);
                        tint = past ? new Color(0.39f, 0.31f, 0.25f, 1f) : new Color(0.27f, 0.28f, 0.28f, 1f);
                        alpha = (0.10f + roofStep * 0.48f) * edgeFade;
                    }

                    var dither = ((((x * 19) ^ (y * 37) ^ (seed * 11)) & 15) / 15f);
                    alpha = Mathf.Clamp01(alpha * Mathf.Lerp(0.82f, 1.0f, dither));
                    pixels[(y * texture.width) + x] = new Color32(
                        (byte)Mathf.Clamp(Mathf.RoundToInt(tint.r * 255f), 0, 255),
                        (byte)Mathf.Clamp(Mathf.RoundToInt(tint.g * 255f), 0, 255),
                        (byte)Mathf.Clamp(Mathf.RoundToInt(tint.b * 255f), 0, 255),
                        (byte)Mathf.Clamp(Mathf.RoundToInt(alpha * 255f), 0, 255));
                }
            }

            texture.SetPixels32(pixels);
            texture.Apply(false, false);
            EditorUtility.SetDirty(texture);
            AssetDatabase.SaveAssets();
            return texture;
        }

        private static Texture2D EnsureHd2dOutdoorSkyWashTexture(string id, bool past, FastVsHouseArea area)
        {
            var path = $"{TextureDirectory}/FastVS_House_{id}.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture != null && (texture.width != 128 || texture.height != 256 || texture.format != TextureFormat.RGBA32 || TextureAlphaChannelIsEmpty(texture)))
            {
                AssetDatabase.DeleteAsset(path);
                texture = null;
            }

            if (texture == null)
            {
                texture = new Texture2D(128, 256, TextureFormat.RGBA32, false);
                AssetDatabase.CreateAsset(texture, path);
            }

            texture.name = $"FastVS_House_{id}";
            texture.filterMode = FilterMode.Bilinear;
            texture.wrapMode = TextureWrapMode.Clamp;
            var seed = (past ? 97 : 23) + (area == FastVsHouseArea.Exterior ? 11 : 47);
            var pixels = new Color32[texture.width * texture.height];

            for (var y = 0; y < texture.height; y++)
            {
                var v = y / 255f;
                for (var x = 0; x < texture.width; x++)
                {
                    var u = x / 127f;
                    var horizontalFade = SmoothFade01(0f, 0.18f, u) * SmoothFade01(0f, 0.18f, 1f - u);
                    var verticalFade = SmoothFade01(0f, 0.10f, v) * SmoothFade01(0f, 0.18f, 1f - v);
                    var lowerBand = Mathf.Exp(-Mathf.Pow((v - 0.28f) / 0.16f, 2f));
                    var upperMist = Mathf.Exp(-Mathf.Pow((v - 0.64f) / 0.30f, 2f));
                    var broadSkyWash = SmoothFade01(0.08f, 0.28f, v) * SmoothFade01(0.98f, 0.72f, v);
                    var horizonWobble = (Mathf.Sin((u * 5.85f) + (seed * 0.29f)) * 0.015f) +
                                        (Mathf.Sin((u * 11.4f) + (seed * 0.11f)) * 0.006f);
                    var horizonHaze = Mathf.Exp(-Mathf.Pow((v - (0.28f + horizonWobble)) / 0.045f, 2f));
                    horizonHaze *= Mathf.Clamp01(0.85f - Mathf.Abs(u - 0.5f) * 1.30f);

                    var cloudDriftA = (Mathf.Sin((u * 6.6f) + (seed * 0.17f)) * 0.012f) + (Mathf.Sin((u * 12.8f) + (seed * 0.09f)) * 0.005f);
                    var cloudCenterA = 0.64f + cloudDriftA;
                    var cloudBandA = Mathf.Exp(-Mathf.Pow((v - cloudCenterA) / 0.026f, 2f));
                    cloudBandA *= Mathf.Clamp01(0.72f - Mathf.Abs(u - 0.5f) * 1.10f);

                    var cloudDriftB = (Mathf.Sin((u * 8.1f) + (seed * 0.21f)) * 0.010f) + (Mathf.Sin((u * 15.8f) + (seed * 0.07f)) * 0.004f);
                    var cloudCenterB = 0.74f + cloudDriftB;
                    var cloudBandB = Mathf.Exp(-Mathf.Pow((v - cloudCenterB) / 0.020f, 2f));
                    cloudBandB *= Mathf.Clamp01(0.60f - Mathf.Abs(u - 0.5f) * 0.88f);

                    var baseAlpha = ((broadSkyWash * 0.020f) + (lowerBand * 0.11f) + (upperMist * 0.085f) + (horizonHaze * 0.070f) + (cloudBandA * 0.055f) + (cloudBandB * 0.040f)) * horizontalFade * verticalFade;
                    var dither = ((((x * 13) ^ (y * 29) ^ (x * y * 7)) & 15) / 15f);
                    var alpha = Mathf.Clamp(baseAlpha * Mathf.Lerp(0.90f, 1.0f, dither) * 0.40f, 0f, past ? 0.10f : 0.11f);

                    Color lowerColor;
                    Color upperColor;
                    Color hazeColor;
                    Color cloudColor;
                    if (area == FastVsHouseArea.Exterior)
                    {
                        lowerColor = past ? new Color(0.39f, 0.34f, 0.30f, 1f) : new Color(0.29f, 0.35f, 0.40f, 1f);
                        upperColor = past ? new Color(0.57f, 0.50f, 0.44f, 1f) : new Color(0.42f, 0.49f, 0.56f, 1f);
                        hazeColor = past ? new Color(0.61f, 0.55f, 0.49f, 1f) : new Color(0.50f, 0.56f, 0.60f, 1f);
                        cloudColor = past ? new Color(0.50f, 0.45f, 0.40f, 1f) : new Color(0.39f, 0.46f, 0.52f, 1f);
                    }
                    else
                    {
                        lowerColor = past ? new Color(0.37f, 0.32f, 0.28f, 1f) : new Color(0.28f, 0.33f, 0.37f, 1f);
                        upperColor = past ? new Color(0.55f, 0.48f, 0.41f, 1f) : new Color(0.40f, 0.46f, 0.53f, 1f);
                        hazeColor = past ? new Color(0.58f, 0.52f, 0.45f, 1f) : new Color(0.49f, 0.54f, 0.58f, 1f);
                        cloudColor = past ? new Color(0.48f, 0.42f, 0.37f, 1f) : new Color(0.37f, 0.44f, 0.49f, 1f);
                    }

                    var tint = Color.Lerp(lowerColor, upperColor, Mathf.SmoothStep(0f, 1f, v));
                    tint = Color.Lerp(tint, hazeColor, Mathf.Clamp01(horizonHaze * 0.30f));
                    tint = Color.Lerp(tint, cloudColor, Mathf.Clamp01((cloudBandA + cloudBandB) * 0.18f));
                    pixels[(y * texture.width) + x] = new Color32(
                        (byte)Mathf.Clamp(Mathf.RoundToInt(tint.r * 255f), 0, 255),
                        (byte)Mathf.Clamp(Mathf.RoundToInt(tint.g * 255f), 0, 255),
                        (byte)Mathf.Clamp(Mathf.RoundToInt(tint.b * 255f), 0, 255),
                        (byte)Mathf.Clamp(Mathf.RoundToInt(alpha * 255f), 0, 255));
                }
            }

            texture.SetPixels32(pixels);
            texture.Apply(false, false);
            EditorUtility.SetDirty(texture);
            AssetDatabase.SaveAssets();
            return texture;
        }

        private static Texture2D EnsureHd2dCinematicSkyVeilTexture()
        {
            return EnsureGeneratedTexture(
                "hd2d_cinematic_sky_veil_cycle84",
                192,
                128,
                FilterMode.Bilinear,
                (x, y) =>
                {
                    var u = (x / 191f) * 2f - 1f;
                    var v = (y / 127f) * 2f - 1f;
                    var vignette = Mathf.Clamp01(1f - Mathf.Sqrt((u * u * 0.88f) + (v * v * 1.22f)));
                    var upperBias = Mathf.Clamp01(1f - ((v + 0.18f) * 0.58f));
                    var lowerFade = Mathf.Clamp01(1f - ((-v + 0.02f) * 0.78f));
                    var centralFade = Mathf.Clamp01(1f - Mathf.Sqrt((u * u * 1.12f) + ((v + 0.02f) * (v + 0.02f) * 1.34f)));
                    var alpha = ((vignette * 0.020f) + (upperBias * 0.034f) + (centralFade * 0.016f)) * lowerFade;
                    alpha = Mathf.Clamp(alpha, 0f, 0.085f);

                    var cool = Color.Lerp(new Color(0.56f, 0.62f, 0.66f, 1f), new Color(0.72f, 0.76f, 0.78f, 1f), Mathf.Clamp01((v + 1f) * 0.48f));
                    var muted = Color.Lerp(cool, new Color(0.64f, 0.68f, 0.70f, 1f), Mathf.Clamp01(vignette * 0.24f));
                    return new Color(muted.r, muted.g, muted.b, alpha);
                });
        }

        private static Texture2D EnsureHd2dCinematicSunDiscTexture()
        {
            return EnsureGeneratedTexture(
                "hd2d_cinematic_sun_disc_cycle84",
                128,
                128,
                FilterMode.Bilinear,
                (x, y) =>
                {
                    var u = (x / 127f) * 2f - 1f;
                    var v = (y / 127f) * 2f - 1f;
                    var core = Mathf.Clamp01(1f - Mathf.Sqrt((u * u * 1.08f) + (v * v * 1.08f)));
                    var halo = Mathf.Clamp01(1f - Mathf.Sqrt((u * u * 0.62f) + (v * v * 0.62f)));
                    var bloom = Mathf.Clamp01(1f - Mathf.Sqrt((u * u * 0.34f) + (v * v * 0.34f)));
                    var edgeBias = Mathf.Clamp01(1f - Mathf.Abs(v) * 0.82f);
                    var alpha = ((core * 0.30f) + (halo * halo * 0.16f) + (bloom * 0.04f)) * edgeBias;
                    alpha = Mathf.Clamp(alpha, 0f, 0.36f);

                    var warm = Color.Lerp(new Color(1.00f, 0.90f, 0.68f, 1f), new Color(1.00f, 0.80f, 0.42f, 1f), Mathf.Clamp01(1f - core));
                    var haloColor = Color.Lerp(warm, new Color(1.00f, 0.96f, 0.86f, 1f), Mathf.Clamp01(halo * 0.52f));
                    return new Color(haloColor.r, haloColor.g, haloColor.b, alpha);
                });
        }

        private static Material EnsureHd2dCinematicSkyVeilMaterial()
        {
            var material = FlatMaterial("hd2d_cinematic_sky_veil_cycle84", Color.white, true, FastVsHd2dMaterialRole.OverlayGlow);
            ConfigureTransparentUnlitMaterial(material, 3006);
            var texture = EnsureHd2dCinematicSkyVeilTexture();
            AssignMaterialTexture(material, texture, Vector2.one);

            var tint = new Color(0.78f, 0.84f, 0.88f, 0.34f);
            if (material.HasProperty("_BaseColor"))
            {
                material.SetColor("_BaseColor", tint);
            }

            if (material.HasProperty("_Color"))
            {
                material.SetColor("_Color", tint);
            }

            EditorUtility.SetDirty(material);
            AssetDatabase.SaveAssets();
            return material;
        }

