            {
                name = "FastVS_House_character_directional_cast_shadow_soft",
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp
            };

            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var u = x / 95f;
                    var v = y / 63f;
                    var coreDx = (u - 0.50f) / 0.34f;
                    var coreDy = (v - 0.53f) / 0.16f;
                    var core = Mathf.Clamp01(1f - Mathf.Sqrt((coreDx * coreDx) + (coreDy * coreDy)));
                    var tailDx = (u - 0.76f) / 0.20f;
                    var tailDy = (v - 0.53f) / 0.12f;
                    var tail = Mathf.Clamp01(1f - Mathf.Sqrt((tailDx * tailDx) + (tailDy * tailDy * 1.55f)));
                    var alpha = (core * 0.29f) + (tail * 0.12f);
                    alpha *= Mathf.Lerp(0.88f, 1f, Mathf.Clamp01(1f - Mathf.Abs(v - 0.53f) / 0.28f));
                    alpha = Mathf.Clamp(alpha, 0f, 0.33f);
                    texture.SetPixel(x, y, new Color(0.03f, 0.035f, 0.05f, alpha));
                }
            }

            texture.Apply(false, false);
            File.WriteAllBytes(path, texture.EncodeToPNG());
            UnityEngine.Object.DestroyImmediate(texture);
            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceSynchronousImport);

            var importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer != null)
            {
                importer.textureType = TextureImporterType.Default;
                importer.alphaIsTransparency = true;
                importer.isReadable = true;
                importer.mipmapEnabled = false;
                importer.npotScale = TextureImporterNPOTScale.None;
                importer.filterMode = FilterMode.Bilinear;
                importer.wrapMode = TextureWrapMode.Clamp;
                importer.textureCompression = TextureImporterCompression.Uncompressed;
                importer.SaveAndReimport();
            }

            var imported = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (imported == null)
            {
                throw new InvalidOperationException($"Fast VS directional cast shadow texture generation failed: {path}");
            }

            return imported;
        }

        private static Texture2D EnsureStaticDirectionalCastShadowTexture()
        {
            EnsureFolder(TextureDirectory);

            var path = $"{TextureDirectory}/FastVS_House_static_directional_cast_shadow_soft.png";
            var texture = new Texture2D(160, 80, TextureFormat.RGBA32, false)
            {
                name = "FastVS_House_static_directional_cast_shadow_soft",
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp
            };

            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var u = x / 159f;
                    var v = y / 79f;
                    var edgeMask =
                        SmoothFade01(0.00f, 0.03f, u) *
                        SmoothFade01(0.00f, 0.09f, 1f - u) *
                        SmoothFade01(0.00f, 0.05f, v) *
                        SmoothFade01(0.00f, 0.07f, 1f - v);

                    var coreDx = (u - 0.41f) / 0.15f;
                    var coreDy = (v - 0.54f) / 0.09f;
                    var core = Mathf.Clamp01(1f - Mathf.Sqrt((coreDx * coreDx * 1.05f) + (coreDy * coreDy * 1.55f)));
                    core = core * core;

                    var tailStart = new Vector2(0.44f, 0.54f);
                    var tailEnd = new Vector2(0.82f, 0.48f);
                    var tailSegment = tailEnd - tailStart;
                    var tailLengthSq = Mathf.Max(0.0001f, Vector2.Dot(tailSegment, tailSegment));
                    var tailT = Mathf.Clamp01(Vector2.Dot(new Vector2(u, v) - tailStart, tailSegment) / tailLengthSq);
                    var tailClosest = tailStart + (tailSegment * tailT);
                    var tailRadius = Mathf.Lerp(0.078f, 0.034f, tailT);
                    var tailDistance = Vector2.Distance(new Vector2(u, v), tailClosest);
                    var tail = Mathf.Clamp01(1f - (tailDistance / tailRadius));
                    tail = tail * tail;

                    var tailCapDx = (u - 0.70f) / 0.11f;
                    var tailCapDy = (v - 0.50f) / 0.08f;
                    var tailCap = Mathf.Clamp01(1f - Mathf.Sqrt((tailCapDx * tailCapDx * 1.10f) + (tailCapDy * tailCapDy * 1.70f)));
                    tailCap = tailCap * tailCap;

                    var bridgeDx = (u - 0.505f) / 0.13f;
                    var bridgeDy = (v - 0.505f) / 0.080f;
                    var bridge = Mathf.Clamp01(1f - Mathf.Sqrt((bridgeDx * bridgeDx * 0.92f) + (bridgeDy * bridgeDy * 1.85f)));

                    var alpha = (tail * 0.112f) + (core * 0.205f) + (tailCap * 0.026f) + (bridge * 0.128f);
                    alpha *= Mathf.Lerp(0.95f, 1f, edgeMask);
                    var noiseSeed = (((x * 17) ^ (y * 29) ^ (x * y * 5)) & 31) / 31f;
                    alpha += (noiseSeed - 0.5f) * 0.0045f;
                    alpha = Mathf.Clamp(alpha * edgeMask, 0f, 0.30f);
                    texture.SetPixel(x, y, new Color(0.03f, 0.035f, 0.045f, alpha));
                }
            }

            texture.Apply(false, false);
            File.WriteAllBytes(path, texture.EncodeToPNG());
            UnityEngine.Object.DestroyImmediate(texture);
            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceSynchronousImport);

            var importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer != null)
            {
                importer.textureType = TextureImporterType.Default;
                importer.alphaIsTransparency = true;
                importer.isReadable = true;
                importer.mipmapEnabled = false;
                importer.npotScale = TextureImporterNPOTScale.None;
                importer.filterMode = FilterMode.Bilinear;
                importer.wrapMode = TextureWrapMode.Clamp;
                importer.textureCompression = TextureImporterCompression.Uncompressed;
                importer.SaveAndReimport();
            }

            var imported = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (imported == null)
            {
                throw new InvalidOperationException($"Fast VS static directional cast shadow texture generation failed: {path}");
            }

            return imported;
        }

        private static Texture2D EnsureSurfaceDirectionalShadeOverlayTexture()
        {
            EnsureFolder(TextureDirectory);

            var path = $"{TextureDirectory}/FastVS_House_surface_directional_shade_overlay_soft.png";
            var texture = new Texture2D(128, 128, TextureFormat.RGBA32, false)
            {
                name = "FastVS_House_surface_directional_shade_overlay_soft",
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp
            };

            var pixels = new Color32[texture.width * texture.height];
            for (var y = 0; y < texture.height; y++)
            {
                var v = y / 127f;
                for (var x = 0; x < texture.width; x++)
                {
                    var u = x / 127f;
                    var xEdge = SmoothFade01(0f, 0.12f, u) * SmoothFade01(0f, 0.18f, 1f - u);
                    var yEdge = SmoothFade01(0f, 0.10f, v) * SmoothFade01(0f, 0.16f, 1f - v);
                    var edgeMask = xEdge * yEdge;
                    var diagonal = Mathf.Clamp01(1f - ((u * 0.92f) + (v * 0.68f)));
                    var upperLeftFocus = Mathf.Clamp01(1f - Mathf.Sqrt(((u / 0.62f) * (u / 0.62f)) + ((v / 0.78f) * (v / 0.78f))));
                    var centerBulge = Mathf.Clamp01(1f - Mathf.Sqrt((((u - 0.44f) / 0.46f) * ((u - 0.44f) / 0.46f)) + (((v - 0.38f) / 0.52f) * ((v - 0.38f) / 0.52f))));
                    var alpha = (0.060f + (diagonal * 0.100f) + (upperLeftFocus * 0.045f) + (centerBulge * 0.060f)) * 1.60f;
                    var noiseSeed = (((x * 17) ^ (y * 29) ^ (x * y * 3)) & 31) / 31f;
                    alpha += (noiseSeed - 0.5f) * 0.008f;
                    alpha = Mathf.Clamp(edgeMask * alpha, 0f, 0.30f);
                    var rgb = new Color32(11, 12, 19, (byte)Mathf.Clamp(Mathf.RoundToInt(alpha * 255f), 0, 255));
                    pixels[(y * texture.width) + x] = rgb;
                }
            }

            texture.SetPixels32(pixels);
            texture.Apply(false, false);
            File.WriteAllBytes(path, texture.EncodeToPNG());
            UnityEngine.Object.DestroyImmediate(texture);
            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceSynchronousImport);

            var importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer != null)
            {
                importer.textureType = TextureImporterType.Default;
                importer.alphaIsTransparency = true;
                importer.isReadable = true;
                importer.mipmapEnabled = false;
                importer.npotScale = TextureImporterNPOTScale.None;
                importer.filterMode = FilterMode.Bilinear;
                importer.wrapMode = TextureWrapMode.Clamp;
                importer.textureCompression = TextureImporterCompression.Uncompressed;
                importer.SaveAndReimport();
            }

            var imported = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (imported == null)
            {
                throw new InvalidOperationException($"Fast VS surface directional shade overlay texture generation failed: {path}");
            }

            return imported;
        }

