        private static Texture2D EnsureGeneratedTexture(string id, int width, int height, FilterMode filterMode, Func<int, int, Color> sample)
        {
            var path = $"{TextureDirectory}/FastVS_House_{id}.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture == null)
            {
                texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
                AssetDatabase.CreateAsset(texture, path);
            }

            texture.name = $"FastVS_House_{id}";
            texture.filterMode = filterMode;
            texture.wrapMode = TextureWrapMode.Clamp;

            for (var y = 0; y < height; y++)
            {
                for (var x = 0; x < width; x++)
                {
                    texture.SetPixel(x, y, sample(x, y));
                }
            }

            texture.Apply(false, false);
            EditorUtility.SetDirty(texture);
            return texture;
        }

        private static Texture2D EnsureGeneratedRepeatTexture(string id, int width, int height, Func<int, int, Color> sample)
        {
            var path = $"{TextureDirectory}/FastVS_House_{id}.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture != null && (texture.width != width || texture.height != height))
            {
                AssetDatabase.DeleteAsset(path);
                texture = null;
            }

            if (texture == null)
            {
                texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
                AssetDatabase.CreateAsset(texture, path);
            }

            texture.name = $"FastVS_House_{id}";
            texture.filterMode = FilterMode.Point;
            texture.wrapMode = TextureWrapMode.Repeat;

            for (var y = 0; y < height; y++)
            {
                for (var x = 0; x < width; x++)
                {
                    texture.SetPixel(x, y, sample(x, y));
                }
            }

            texture.Apply(false, false);
            EditorUtility.SetDirty(texture);
            return texture;
        }

        private static Texture2D EnsureOpenGameArtBookshelfFrontTexture()
        {
            EnsureTextureImporter(OpenGameArtBookshelfTexturePath);
            var source = AssetDatabase.LoadAssetAtPath<Texture2D>(OpenGameArtBookshelfTexturePath);
            if (source == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing OpenGameArt bookshelf source texture at {OpenGameArtBookshelfTexturePath}.");
            }

            var path = $"{TextureDirectory}/FastVS_House_bookshelf_front_painted_hd2d.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture != null && (texture.width != 256 || texture.height != 128))
            {
                AssetDatabase.DeleteAsset(path);
                texture = null;
            }

            if (texture == null)
            {
                texture = new Texture2D(256, 128, TextureFormat.RGBA32, false);
                AssetDatabase.CreateAsset(texture, path);
            }

            texture.name = "FastVS_House_bookshelf_front_painted_hd2d";
            texture.filterMode = FilterMode.Point;
            texture.wrapMode = TextureWrapMode.Repeat;

            const int cropX = 16;
            const int cropY = 2;
            const int cropWidth = 34;
            const int cropHeight = 60;
            var shelfRecess = new Color(0.10f, 0.075f, 0.045f, 1f);

            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var sample = source.GetPixel(cropX + (x % cropWidth), cropY + (y % cropHeight));
                    if (sample.a <= 0.03f)
                    {
                        sample = shelfRecess;
                    }
                    else
                    {
                        sample = LerpColor(sample, new Color(0.24f, 0.16f, 0.09f, 1f), 0.38f);
                        sample = Darken(sample, 0.10f);
                    }

                    texture.SetPixel(x, y, sample);
                }
            }

            texture.Apply(false, false);
            EditorUtility.SetDirty(texture);
            return texture;
        }

        private static Material PaintedSurfaceMaterial(string materialId, string textureId, int width, int height, Func<int, int, Color> sample, bool unlit, Vector2 tiling, FastVsHd2dMaterialRole role = FastVsHd2dMaterialRole.SurfaceLit)
        {
            var material = FlatMaterial(materialId, Color.white, unlit, role);
            var texture = EnsureGeneratedRepeatTexture(textureId, width, height, sample);
            AssignMaterialTexture(material, texture, tiling);
            return material;
        }

