                    break;
                }
            }

            if (Hash01(x, y, seed + 31) > 0.988f)
            {
                baseTone = Darken(baseTone, 0.20f);
            }

            return ShadeSurface(baseTone, x, y, width, height, 0.16f, 0.08f);
        }

