        private static Material SpriteMaterial(string id, string texturePath, Color tint, bool strip = false)
        {
            return SpriteStripMaterial(id, texturePath, tint, strip ? NiroAnimatedFrameCount : 1);
        }

        private static Material ExternalSpriteMaterial(string id, string texturePath, Color tint)
        {
            EnsureTextureImporter(texturePath);
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(texturePath);
            var material = CreateSpriteCardMaterial(id, tint, 3011);
            if (texture == null)
            {
                throw new InvalidOperationException($"Fast VS external sprite texture missing: {texturePath}");
            }

            AssignMaterialTexture(material, texture, Vector2.one);

            EditorUtility.SetDirty(material);
            return material;
        }

        private static Material SpriteStripMaterial(string id, string texturePath, Color tint, int frameCount)
        {
            EnsureTextureImporter(texturePath);
            var material = CreateSpriteCardMaterial(id, tint, 3000);
            var texture = EnsureShadedSpriteTexture(id, texturePath);
            if (texture == null)
            {
                Debug.LogWarning($"Fast VS character texture missing: {texturePath}");
                return material;
            }

            AssignMaterialTexture(material, texture, frameCount > 1 ? new Vector2(1f / frameCount, 1f) : Vector2.one);
            EditorUtility.SetDirty(material);
            return material;
        }

        private static void EnsureTextureImporter(string texturePath)
        {
            AssetDatabase.ImportAsset(texturePath, ImportAssetOptions.ForceSynchronousImport);
            var importer = AssetImporter.GetAtPath(texturePath) as TextureImporter;
            if (importer == null)
            {
                return;
            }

            importer.textureType = TextureImporterType.Default;
            importer.alphaIsTransparency = true;
            importer.isReadable = true;
            importer.mipmapEnabled = false;
            importer.npotScale = TextureImporterNPOTScale.None;
            importer.filterMode = FilterMode.Point;
            importer.textureCompression = TextureImporterCompression.Uncompressed;
            importer.SaveAndReimport();
        }

        private static Texture2D EnsureShadedSpriteTexture(string id, string texturePath)
        {
            var source = AssetDatabase.LoadAssetAtPath<Texture2D>(texturePath);
            if (source == null)
            {
                Debug.LogWarning($"Fast VS character texture missing: {texturePath}");
                return null;
            }

            var path = $"{TextureDirectory}/FastVS_House_{id}_shaded.asset";
            var shaded = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (shaded != null && (shaded.width != source.width || shaded.height != source.height))
            {
                AssetDatabase.DeleteAsset(path);
                shaded = null;
            }

            if (shaded == null)
            {
                shaded = new Texture2D(source.width, source.height, TextureFormat.RGBA32, false);
                AssetDatabase.CreateAsset(shaded, path);
            }

            shaded.name = $"FastVS_House_{id}_shaded";
            shaded.filterMode = FilterMode.Point;
            shaded.wrapMode = TextureWrapMode.Clamp;

            for (var y = 0; y < source.height; y++)
            {
                for (var x = 0; x < source.width; x++)
                {
                    shaded.SetPixel(x, y, ShadeSpritePixel(source.GetPixel(x, y), x, y, source.width, source.height));
                }
            }

            shaded.Apply(false, false);
            EditorUtility.SetDirty(shaded);
            return shaded;
        }

        private static Color ShadeSpritePixel(Color source, int x, int y, int width, int height)
        {
            if (source.a <= 0.03f)
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            var frameWidth = GetSpriteFrameWidth(width, height);
            var frameX = x % frameWidth;
            var u = frameWidth <= 1 ? 0f : frameX / (float)(frameWidth - 1);
            var v = height <= 1 ? 0f : y / (float)(height - 1);

            var left = 1f - u;
            var right = u;
            var top = v;
            var bottom = 1f - v;

            var warmKey = Mathf.Clamp01(left * top);
            var coolShadow = Mathf.Clamp01(right * bottom);
            var contactDark = Mathf.Clamp01(bottom * bottom * Mathf.Clamp01(1f - Mathf.Abs(u - 0.5f) * 1.7f));
            var rimLight = Mathf.Clamp01(Mathf.Max(0f, left * 0.74f + top * 0.42f - 0.72f)) * Mathf.Clamp01((source.a - 0.12f) / 0.88f);

            var luminance = GetSpriteLuminance(source);
            var luminanceScale = 1f + (warmKey * 0.14f) + (rimLight * 0.05f) - (coolShadow * 0.17f) - (contactDark * 0.14f);
            luminanceScale = Mathf.Clamp(luminanceScale, 0.64f, 1.22f);

            var tinted = new Color(
                source.r * luminanceScale * (1f + warmKey * 0.03f - coolShadow * 0.015f + rimLight * 0.02f),
                source.g * luminanceScale * (1f + warmKey * 0.02f - coolShadow * 0.010f + rimLight * 0.016f),
                source.b * luminanceScale * (1f - warmKey * 0.018f + coolShadow * 0.045f + rimLight * 0.010f),
                source.a);

            var shadedLuminance = GetSpriteLuminance(tinted);
            if (shadedLuminance > 0.0001f)
            {
                var minimum = luminance > 0.16f ? 0.09f : 0.035f;
                var maximum = Mathf.Clamp(luminance * 1.3f, 0.24f, 0.94f);
                if (shadedLuminance < minimum || shadedLuminance > maximum)
                {
                    var targetLuminance = Mathf.Clamp(shadedLuminance, minimum, maximum);
                    var clampScale = targetLuminance / shadedLuminance;
                    tinted.r = Mathf.Clamp01(tinted.r * clampScale);
                    tinted.g = Mathf.Clamp01(tinted.g * clampScale);
                    tinted.b = Mathf.Clamp01(tinted.b * clampScale);
                }
            }

            return tinted;
        }

        private static int GetSpriteFrameWidth(int width, int height)
        {
            if (height == NiroExpectedTextureHeight && width > NiroExpectedTextureWidth && width % NiroExpectedTextureWidth == 0)
            {
                return NiroExpectedTextureWidth;
            }

            return Mathf.Max(1, width);
        }

        private static float GetSpriteLuminance(Color color)
        {
            return (color.r * 0.2126f) + (color.g * 0.7152f) + (color.b * 0.0722f);
        }

